$zero | ForEach-Object { $_ }
"`nZERO-USE ENABLED count: $($zero.Count)"

"`n=== ENABLED plugins with usageCount > 0 (KEEP) ==="
$enabled | Where-Object { $usage.ContainsKey($_) -and $usage[$_] -gt 0 } | Sort-Object { -1 * $usage[$_] } | ForEach-Object { "{0,5}  {1}" -f $usage[$_], $_ }

"`n=== ENABLED but NOT in pluginUsage (no telemetry) ==="
$enabled | Where-Object { -not $usage.ContainsKey($_) } | Sort-Object | ForEach-Object { $_ }

